import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        if (n > 11) {
            pw.println(0);
            pw.close();
            sc.close();
            return;
        }

        int[][] pts = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                pts[i][j] = sc.nextInt();
            }
        }

        List<Integer> good = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n && ok; j++) {
                for (int k = 0; k < n && ok; k++) {
                    if (i != j && i != k && j != k) {
                        int[] v1 = new int[5];
                        int[] v2 = new int[5];
                        for (int d = 0; d < 5; d++) {
                            v1[d] = pts[j][d] - pts[i][d];
                            v2[d] = pts[k][d] - pts[i][d];
                        }
                        long dot = 0;
                        for (int d = 0; d < 5; d++) {
                            dot += (long)v1[d] * v2[d];
                        }
                        if (dot > 0) ok = false;
                    }
                }
            }
            if (ok) good.add(i + 1);
        }

        if (good.isEmpty()) {
            pw.println(0);
        } else {
            pw.println(good.size());
            for (int x : good) pw.println(x);
        }

        pw.close();
        sc.close();
    }

    static class Scanner {
        private BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
